## 5. Database Schema

```sql
CREATE TABLE Transactions (
    TransactionId UUID PRIMARY KEY,
    AccountId UUID NOT NULL,
    Timestamp TIMESTAMP WITH TIME ZONE NOT NULL,
    Amount DECIMAL(18, 2) NOT NULL,
    Currency VARCHAR(3) NOT NULL,
    TransactionType VARCHAR(50) NOT NULL,
    MerchantCategory VARCHAR(100),
    Location VARCHAR(100),
    IsSuspicious BOOLEAN NOT NULL DEFAULT FALSE
);

CREATE INDEX idx_transactions_timestamp ON Transactions (Timestamp);
CREATE INDEX idx_transactions_accountid ON Transactions (AccountId);

CREATE TABLE Alerts (
    AlertId UUID PRIMARY KEY,
    TransactionId UUID REFERENCES Transactions(TransactionId),
    AccountId UUID NOT NULL,
    Timestamp TIMESTAMP WITH TIME ZONE NOT NULL,
    Reason TEXT NOT NULL,
    AnomalyScore REAL NOT NULL,
    Status VARCHAR(20) NOT NULL DEFAULT 'New' -- e.g., New, Investigating, Closed
);

CREATE INDEX idx_alerts_accountid ON Alerts (AccountId);
CREATE INDEX idx_alerts_timestamp ON Alerts (Timestamp);

-- Seed Data (Example for initial testing)
