## 7. Key Service Implementations

**`TransactionService.cs` (in `Aml.Monitoring.Api/Services/`)**

```csharp
public class TransactionService : ITransactionService
{
    private readonly ITransactionRepository _transactionRepository;
    private readonly IAnomalyDetectionService _anomalyDetectionService;
    private readonly IAlertingService _alertingService;

    public TransactionService(
        ITransactionRepository transactionRepository,
        IAnomalyDetectionService anomalyDetectionService,
        IAlertingService alertingService)
    {
        _transactionRepository = transactionRepository;
        _anomalyDetectionService = anomalyDetectionService;
        _alertingService = alertingService;
    }

    public async Task<Transaction> ProcessTransactionAsync(Transaction transaction)
    {
        // 1. Save the raw transaction to the database.
        await _transactionRepository.AddTransactionAsync(transaction);

        // 2. Detect anomalies using the ML model.
        AnomalyScore score = await _anomalyDetectionService.DetectAnomalyAsync(transaction);

        // 3. Determine if the transaction is suspicious based on a threshold.
        bool isSuspicious = score.Score > 0.8; // Example threshold
        transaction = transaction with { IsSuspicious = isSuspicious };

        // 4. If suspicious, create an alert.
        if (isSuspicious)
        {
            await _alertingService.CreateAlertAsync(
                Guid.NewGuid(),
                transaction.TransactionId,
                transaction.AccountId,
                DateTimeOffset.UtcNow,
                "High anomaly score detected",
                score.Score);
        }

        // 5. Update the transaction with its suspicious status (optional, depending on requirements).
        await _transactionRepository.UpdateTransactionAsync(transaction);

        return transaction;
    }
}
```

